/**
 * Normaliza el lead que llega de /api/interest.
 *
 * El email es la clave de deduplicacion a nivel de CONTACTO, asi que se
 * normaliza aqui y no en cada sitio que lo use: minusculas y sin espacios.
 *
 * Este webhook es alcanzable por su cuenta, asi que no se fia de quien le
 * llame aunque el endpoint web ya valide lo mismo.
 */
const body = $json.body ?? $json;

const email = String(body?.contact?.email ?? '').trim().toLowerCase();
if (!email) throw new Error('Lead sin email: no hay clave de deduplicacion.');
if (body?.consent?.accepted !== true) throw new Error('Lead sin consentimiento: no se guarda.');

const txt = (v, max = 2000) => String(v ?? '').slice(0, max);

const fullName = txt(body?.contact?.name, 200) || email;
// El CRM separa nombre y apellidos; el formulario pide un solo campo.
// Se parte por el primer espacio, que acierta en la mayoria y no inventa nada:
// lo que llego entero sigue estando en "Full Name".
const parts = fullName.split(/\s+/);
const firstName = parts[0] ?? '';
const lastName = parts.slice(1).join(' ');

return [{
  json: {
    email,
    fullName,
    firstName,
    lastName,
    phone: txt(body?.contact?.phone, 50),
    reason: txt(body?.reason),
    projectName: txt(body?.project?.name, 200),
    projectSlug: txt(body?.project?.slug, 200),
    consentVersion: txt(body?.consent?.version, 40),
    consentAt: txt(body?.consent?.acceptedAt, 40),
    pageUrl: txt(body?.attribution?.pageUrl, 2000),
    locale: txt(body?.attribution?.locale, 10),
    utmSource: txt(body?.attribution?.utm_source, 200),
    utmMedium: txt(body?.attribution?.utm_medium, 200),
    utmCampaign: txt(body?.attribution?.utm_campaign, 200),
    utmTerm: txt(body?.attribution?.utm_term, 200),
    utmContent: txt(body?.attribution?.utm_content, 200),
    correlationId: txt(body?.correlationId, 60),
    receivedAt: new Date().toISOString(),
    contactsDb: $('Configuracion').first().json.contactsDb,
    followUpsDb: $('Configuracion').first().json.followUpsDb,
    projectsDb: $('Configuracion').first().json.projectsDb,
  },
}];

/**
 * Decide si el contacto es nuevo y arma sus propiedades.
 *
 * Status y Source SOLO se escriben al crear. Si alguien del equipo ya movio el
 * contacto a "Customer", un formulario posterior no puede devolverlo a
 * "Interested"; y si entro por referido, la web no puede reescribir su origen.
 *
 * Telefono y nombre si se refrescan: es el dato mas reciente que ha dado la
 * propia persona. Un valor vacio nunca pisa uno que ya existe.
 */
const lead = $('Normalizar').first().json;
const found = $json.results ?? [];
const existing = found.length > 0 ? found[0] : null;

const rich = (v) => (v ? [{ text: { content: String(v).slice(0, 2000) } }] : []);

const properties = {
  'Full Name': { title: [{ text: { content: lead.fullName.slice(0, 200) } }] },
  'Email': { email: lead.email },
};

if (lead.firstName) properties['Name'] = { rich_text: rich(lead.firstName) };
if (lead.lastName) properties['Last Name'] = { rich_text: rich(lead.lastName) };
if (lead.phone) properties['Phone'] = { phone_number: lead.phone };

if (!existing) {
  properties['Status'] = { status: { name: 'Interested' } };
  properties['Source'] = { select: { name: 'Web' } };
}

return [{
  json: {
    exists: Boolean(existing),
    contactPageId: existing?.id ?? null,
    contactsDb: lead.contactsDb,
    properties,
  },
}];

/**
 * Arma el Follow-up del envio.
 *
 * Un registro por envio, no uno por persona: cinco consultas de la misma
 * direccion son cinco Follow-ups bajo el mismo contacto. Asi el historial sale
 * solo y no hay que apilar texto dentro de un campo.
 *
 * El proyecto se enlaza por slug. Si no aparece en el CRM se deja la relacion
 * vacia y su nombre queda en el titulo: mejor un lead sin relacion que un lead
 * colgado del proyecto equivocado.
 */
const lead = $('Normalizar').first().json;
const contactId = $('Contacto listo').first().json.contactId;
const projectMatches = $json.results ?? [];
const projectId = projectMatches.length > 0 ? projectMatches[0].id : null;

const rich = (v) => (v ? [{ text: { content: String(v).slice(0, 2000) } }] : []);
const title = `Web enquiry — ${lead.projectName || 'Ardeno'} — ${lead.fullName}`;

const properties = {
  'Follow-up': { title: [{ text: { content: title.slice(0, 200) } }] },
  'Type': { select: { name: 'Web enquiry' } },
  'Client': { relation: [{ id: contactId }] },
  'Notes': { rich_text: rich(lead.reason) },
  'Scheduled': { date: { start: lead.receivedAt } },
  'Page URL': { url: lead.pageUrl || null },
  'Language': { rich_text: rich(lead.locale) },
  'UTM Source': { rich_text: rich(lead.utmSource) },
  'UTM Medium': { rich_text: rich(lead.utmMedium) },
  'UTM Campaign': { rich_text: rich(lead.utmCampaign) },
  'UTM Term': { rich_text: rich(lead.utmTerm) },
  'UTM Content': { rich_text: rich(lead.utmContent) },
  'Consent': { checkbox: true },
  'Consent date': { date: lead.consentAt ? { start: lead.consentAt } : null },
  'Consent version': { rich_text: rich(lead.consentVersion) },
  'Correlation ID': { rich_text: rich(lead.correlationId) },
};

if (projectId) properties['Project'] = { relation: [{ id: projectId }] };

return [{ json: { followUpsDb: lead.followUpsDb, properties } }];
